def dehydrate_timedelta(value):
    """ Dehydrator for `timedelta` values.

    :param value:
    :type value: timedelta
    :return: float
    """
    # Ensure the value is a timedelta-like object
    if not hasattr(value, "total_seconds"):
        raise TypeError(f"Expected a datetime.timedelta-like object, got {type(value).__name__}")

    try:
        # Convert the timedelta to total seconds for serialization
        return value.total_seconds()
    except Exception as exc:
        raise ValueError(f"Failed to dehydrate timedelta: {exc}") from exc

def dehydrate_time(value):
    """Dehydrator for `time` values.

    :param value: The time object to dehydrate.
    :type value: Time
    :return: A string representation of the time in ISO 8601 format.
    :raises ValueError: If the value cannot be dehydrated.
    """
    if value is None:
        return None
    try:
        # Prefer the built‑in isoformat if available
        if hasattr(value, "isoformat"):
            return value.isoformat()
        # Fallback to manual formatting if the object has hour/minute/second attributes
        if all(hasattr(value, attr) for attr in ("hour", "minute", "second")):
            hour = getattr(value, "hour")
            minute = getattr(value, "minute")
            second = getattr(value, "second")
            microsecond = getattr(value, "microsecond", 0)
            if microsecond:
                return f"{hour:02d}:{minute:02d}:{second:02d}.{microsecond:06d}"
            return f"{hour:02d}:{minute:02d}:{second:02d}"
        raise TypeError("Unsupported time-like object")
    except Exception as exc:
        raise ValueError(f"Cannot dehydrate time value: {exc}") from exc

def dehydrate_point(value):
    """ Dehydrator for Point data.

    :param value:
    :type value: Point
    :return: dict with numeric x and y coordinates
    """
    if value is None:
        return None
    # Ensure the object has the expected attributes
    if not hasattr(value, "x") or not hasattr(value, "y"):
        raise TypeError("Expected a Point instance with 'x' and 'y' attributes")
    try:
        x = float(value.x)
        y = float(value.y)
    except (TypeError, ValueError) as exc:
        raise TypeError("Point coordinates must be numeric") from exc
    return {"x": x, "y": y}

def keys(self):
    """ Return the keys of the record.

    :return: list of key names
    """
    # Try common attribute names that might hold the record
    for attr in ("_record", "record", "data"):
        if hasattr(self, attr):
            value = getattr(self, attr)
            if isinstance(value, dict):
                return list(value.keys())
    # If the instance itself is a dict
    if isinstance(self, dict):
        return list(dict.keys(self))
    raise AttributeError("No dictionary-like record found in the object")

def index(self, key):
    """Return the index of the given item.

    :param key: a key
    :return: index
    :rtype: int
    """
    try:
        for idx, item in enumerate(self):
            try:
                if item == key:
                    return idx
            except Exception:
                # If comparison fails, skip this item
                continue
    except TypeError:
        raise TypeError("Object is not iterable")
    raise ValueError(f"{key} is not in list")

def data(self, *keys):
    """ Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    # Ensure the record has the expected attributes
    if not hasattr(self, "_fields") or not hasattr(self, "_data"):
        raise AttributeError("Record object must have '_fields' and '_data' attributes")

    # If no keys are specified, return all fields
    if not keys:
        return {field: self._data.get(field, None) for field in self._fields}

    result = {}
    for key in keys:
        if isinstance(key, int):
            # Index-based lookup
            if key < 0 or key >= len(self._fields):
                raise IndexError(f"Index {key} out of bounds")
            field = self._fields[key]
            result[field] = self._data.get(field, None)
        elif isinstance(key, str):
            # Key-based lookup
            result[key] = self._data.get(key, None)
        else:
            raise TypeError(f"Key {key!r} must be an int or str")
    return result

def pop_u16(self):
    """Remove the last two bytes of data, returning them as a big-endian
    16-bit unsigned integer.
    """
    # Ensure the object has a 'data' attribute
    if not hasattr(self, 'data'):
        raise AttributeError("The object does not have a 'data' attribute")

    data = self.data

    # Accept bytes, bytearray, list of ints, or memoryview
    if isinstance(data, (bytes, bytearray)):
        if len(data) < 2:
            raise ValueError("Not enough data to pop 2 bytes")
        # Extract the last two bytes
        last_two = data[-2:]
        # Remove them from the buffer
        if isinstance(data, bytearray):
            del data[-2:]
        else:  # bytes are immutable
            self.data = data[:-2]
        return int.from_bytes(last_two, 'big')

    if isinstance(data, list):
        if len(data) < 2:
            raise ValueError("Not enough data to pop 2 bytes")
        # Validate list elements
        for i, val in enumerate(data[-2:]):
            if not isinstance(val, int) or not (0 <= val <= 255):
                raise TypeError(f"List element at position {len(data)-2+i} is not a valid byte value")
        last_two = bytes(data[-2:])
        del data[-2:]
        return int.from_bytes(last_two, 'big')

    if isinstance(data, memoryview):
        if len(data) < 2:
            raise ValueError("Not enough data to pop 2 bytes")
        last_two = data[-2:].tobytes()
        # memoryview is read-only; reassign if possible
        try:
            self.data = data[:-2].tobytes()
        except Exception:
            # If reassignment fails, raise an informative error
            raise RuntimeError("Unable to modify the memoryview buffer")
        return int.from_bytes(last_two, 'big')

    raise TypeError("Unsupported data type for 'data' attribute; expected bytes, bytearray, list of ints, or memoryview")

def begin(self, mode=None, bookmarks=None, metadata=None, timeout=None,
              db=None, imp_user=None, dehydration_hooks=None,
              hydration_hooks=None, **handlers):
        """
        Appends a BEGIN message to the output queue.

        :param mode: access mode for routing - "READ" or "WRITE" (default)
        :param bookmarks: iterable of bookmark values after which this transaction should begin
        :param metadata: custom metadata dictionary to attach to the transaction
        :param timeout: timeout for transaction execution (seconds)
        :param db: name of the database against which to begin the transaction
            Requires Bolt 4.0+.
        :param imp_user: the user to impersonate
            Requires Bolt 4.4+
        :param dehydration_hooks:
            Hooks to dehydrate types (dict from type (class) to dehydration
            function). Dehydration functions receive the value and returns an
            object of type understood by packstream.
        :param hydration_hooks:
            Hooks to hydrate types (mapping from type (class) to
            dehydration function). Dehydration functions receive the value of
            type understood by packstream and are free to return anything.
        :param handlers: handler functions passed into the returned Response object
        :return: Response object
        """
        # Validate mode
        if mode is None:
            mode = "WRITE"
        if mode not in ("READ", "WRITE"):
            raise ValueError(f"Invalid mode '{mode}'. Expected 'READ' or 'WRITE'.")

        # Validate bookmarks
        if bookmarks is None:
            bookmarks = []
        else:
            try:
                bookmarks = list(bookmarks)
            except TypeError:
                raise ValueError("bookmarks must be an iterable of bookmark values.")
            for b in bookmarks:
                if not isinstance(b, str):
                    raise ValueError("Each bookmark must be a string.")

        # Validate metadata
        if metadata is None:
            metadata = {}
        elif not isinstance(metadata, dict):
            raise ValueError("metadata must be a dictionary.")

        # Validate timeout
        if timeout is not None:
            if not isinstance(timeout, (int, float)):
                raise ValueError("timeout must be a number (seconds).")
            if timeout <= 0:
                raise ValueError("timeout must be positive.")

        # Validate db
        if db is not None and not isinstance(db, str):
            raise ValueError("db must be a string.")

        # Validate imp_user
        if imp_user is not None and not isinstance(imp_user, str):
            raise ValueError("imp_user must be a string.")

        # Validate dehydration_hooks
        if dehydration_hooks is not None:
            if not isinstance(dehydration_hooks, dict):
                raise ValueError("dehydration_hooks must be a dict mapping type to callable.")
            for t, fn in dehydration_hooks.items():
                if not callable(fn):
                    raise ValueError(f"Dehydration hook for type {t} is not callable.")

        # Validate hydration_hooks
        if hydration_hooks is not None:
            if not isinstance(hydration_hooks, dict):
                raise ValueError("hydration_hooks must be a dict mapping type to callable.")
            for t, fn in hydration_hooks.items():
                if not callable(fn):
                    raise ValueError(f"Hydration hook for type {t} is not callable.")

        # Prepare the BEGIN message
        message = {"type": "BEGIN", "mode": mode}
        if bookmarks:
            message["bookmarks"] = bookmarks
        if metadata:
            message["metadata"] = metadata
        if timeout is not None:
            message["timeout"] = timeout
        if db is not None:
            message["db"] = db
        if imp_user is not None:
            message["imp_user"] = imp_user

        # Store hooks on the session if provided
        if dehydration_hooks is not None:
            setattr(self, "_dehydration_hooks", dehydration_hooks)
        if hydration_hooks is not None:
            setattr(self, "_hydration_hooks", hydration_hooks)

        # Ensure the output queue exists
        if not hasattr(self, "_queue"):
            self._queue = []
        if not isinstance(self._queue, list):
            raise RuntimeError("self._queue must be a list to hold outgoing messages.")

        # Append the message to the queue
        self._queue.append(message)

        # Return a Response object, passing any handlers
        # The Response class is assumed to be available in the context
        return Response(self, handlers)

def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass. """
    # Validate name
    if not isinstance(name, str):
        raise TypeError("name must be a string")
    # Validate fields
    if not isinstance(fields, (list, tuple)):
        raise TypeError("fields must be a list or tuple of field names")
    if len(set(fields)) != len(fields):
        raise ValueError("field names must be unique")
    for f in fields:
        if not isinstance(f, str):
            raise TypeError("each field name must be a string")
    # Validate srid_map
    if not isinstance(srid_map, dict):
        raise TypeError("srid_map must be a dictionary")
    # Determine base class
    try:
        base = Point
    except NameError:
        class Point:
            def __init__(self, **kwargs):
                for key, value in kwargs.items():
                    setattr(self, key, value)
    # Build class dictionary
    class_dict = {
        "__slots__": fields,
        "srid_map": srid_map,
    }
    # Define __init__
    def __init__(self, *args, **kwargs):
        if len(args) > len(fields):
            raise TypeError(f"Expected at most {len(fields)} positional arguments")
        for key, value in zip(fields, args):
            setattr(self, key, value)
        for key in fields[len(args):]:
            if key in kwargs:
                setattr(self, key, kwargs.pop(key))
        if kwargs:
            raise TypeError(f"Unexpected keyword arguments: {', '.join(kwargs.keys())}")
    class_dict["__init__"] = __init__
    # Optional __repr__
    def __repr__(self):
        field_str = ", ".join(f"{k}={getattr(self, k)!r}" for k in fields)
        return f"{name}({field_str})"
    class_dict["__repr__"] = __repr__
    # Create the new class
    new_cls = type(name, (base,), class_dict)
    return new_cls

def deprecated(message):
    """Decorator for deprecating functions and methods.

    Usage:

        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass
    """
    if not isinstance(message, str):
        raise TypeError("message must be a string")
    def decorator(func):
        import functools
        import warnings
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            warnings.warn(message, DeprecationWarning, stacklevel=2)
            return func(*args, **kwargs)
        return wrapper
    return decorator

def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.
    """
    if cache is None:
        raise ValueError("cache must be provided")
    if key is None:
        raise ValueError("key function must be provided")

    def decorator(func):
        if not callable(func):
            raise TypeError("cached decorator expects a callable")

        def wrapper(*args, **kwargs):
            try:
                k = key(args, kwargs)
            except Exception as e:
                raise ValueError(f"Key function raised an exception: {e}") from e

            def _get_or_set():
                try:
                    return cache[k]
                except KeyError:
                    result = func(*args, **kwargs)
                    cache[k] = result
                    return result

            if lock is not None:
                if hasattr(lock, "__enter__"):
                    with lock:
                        return _get_or_set()
                else:
                    lock.acquire()
                    try:
                        return _get_or_set()
                    finally:
                        lock.release()
            else:
                return _get_or_set()

        wrapper.__name__ = func.__name__
        wrapper.__doc__ = func.__doc__
        wrapper.__dict__.update(func.__dict__)
        return wrapper

    return decorator

def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.
    """
    def decorating_function(user_function):
        if maxsize <= 0:
            # No caching if maxsize is non-positive
            return user_function

        cache = {}
        usage = {}

        def make_key(args, kwargs):
            """Create a hashable key from args and kwargs."""
            key = args
            if kwargs:
                # Sort kwargs to ensure consistent ordering
                key += tuple(sorted(kwargs.items()))
            if typed:
                # Include types of arguments in the key
                key += tuple(type(v) for v in args)
                if kwargs:
                    key += tuple(type(v) for _, v in sorted(kwargs.items()))
            return key

        def wrapper(*args, **kwargs):
            try:
                key = make_key(args, kwargs)
            except TypeError:
                # If arguments are not hashable, skip caching
                return user_function(*args, **kwargs)

            if key in cache:
                usage[key] += 1
                return cache[key]

            # Compute the result and store it
            result = user_function(*args, **kwargs)
            cache[key] = result
            usage[key] = 1

            # Evict least frequently used item if cache is full
            if len(cache) > maxsize:
                # Find key with minimum usage count
                min_key = min(usage, key=lambda k: usage[k])
                del cache[min_key]
                del usage[min_key]

            return result

        # Preserve function metadata
        wrapper.__name__ = user_function.__name__
        wrapper.__doc__ = user_function.__doc__
        wrapper.__module__ = user_function.__module__
        wrapper.__dict__.update(user_function.__dict__)

        return wrapper

    return decorating_function

def popitem(self):
    """Remove and return the `(key, value)` pair first inserted."""
    try:
        key = next(iter(self))
    except StopIteration:
        raise KeyError('popitem(): dictionary is empty')
    value = self[key]
    del self[key]
    return key, value

def get(self, key, default=None):
    """D.get(k[,d]) -> D[k] if k in D, else d.  d defaults to None."""
    try:
        return self[key]
    except KeyError:
        return default

def cachedmethod(cache, key=hashkey, lock=None):
    """Decorator to wrap a class or instance method with a memoizing
    callable that saves results in a cache.

    """
    if not callable(key):
        raise TypeError("key must be callable")
    def decorator(func):
        def wrapper(*args, **kwargs):
            k = key(*args, **kwargs)
            if lock:
                try:
                    with lock:
                        if k in cache:
                            return cache[k]
                        result = func(*args, **kwargs)
                        cache[k] = result
                        return result
                except Exception:
                    # Fallback to no lock if lock acquisition fails
                    if k in cache:
                        return cache[k]
                    result = func(*args, **kwargs)
                    cache[k] = result
                    return result
            else:
                if k in cache:
                    return cache[k]
                result = func(*args, **kwargs

@classmethod
    def extostr(cls, e, max_level=30, max_path_level=5):
        """
        Format an exception.
        :param e: Any exception instance.
        :type e: Exception
        :param max_level: Maximum call stack level (default 30)
        :type max_level: int
        :param max_path_level: Maximum path level (default 5)
        :type max_path_level: int
        :return The exception readable string
        :rtype str
        """
        # Basic validation
        if not isinstance(e, BaseException):
            raise TypeError("e must be an exception instance")
        if not isinstance(max_level, int) or max_level <= 0:
            raise ValueError("max_level must be a positive integer")
        if not isinstance(max_path_level, int) or max_path_level <= 0:
            raise ValueError("max_path_level must be a positive integer")

        import traceback
        import os

        parts = []

        # Exception type and message
        parts.append(f"{e.__class__.__name__}: {e}")

        # Traceback extraction
        tb = e.__traceback__
        if tb:
            extracted = traceback.extract_tb(tb)
            if len(extracted) > max_level:
                extracted = extracted[:max_level]
            for frame in extracted:
                # Shorten file path
                path_parts = frame.filename.split(os.sep)
                if len(path_parts) > max_path_level:
                    short_path = os.sep.join(path_parts[-max_path_level:])
                else:
                    short_path = frame.filename
                parts.append(f"  File \"{short_path}\", line {frame.lineno}, in {frame.name}")
                if frame.line:
                    parts.append(f"    {frame.line.strip()}")

        # Handle chained exceptions
        def _append_chain(exc, prefix):
            if exc is None:
                return
            parts.append(prefix)
            parts.append(cls.extostr(exc, max_level, max_path_level))

        if e.__cause__:
            _append_chain(e.__cause__, "Caused by:")
        elif e.__context__:
            _append_chain(e.__context__, "During handling of the above exception, another exception occurred:")

        return "\n".join(parts)

@staticmethod
    def file_to_textbuffer(file_name, encoding):
        """
        Load a file toward a text buffer (UTF-8), using the specify encoding while reading.
        CAUTION : This will read the whole file IN MEMORY.
        :param file_name: File name.
        :type file_name: str
        :param encoding: Encoding to use.
        :type encoding: str
        :return: A text buffer or None in case of error.
        :rtype str
        """
        # Validate input types
        if not isinstance(file_name, str) or not isinstance(encoding, str):
            return None
        try:
            with open(file_name, 'r', encoding=encoding) as f:
                return f.read()
        except (OSError, UnicodeDecodeError, TypeError):
            return None

def is_file_exist(file_name):
        """
        Check if file name exist.
        :param file_name: File name.
        :type file_name: str
        :return: Return true (exist), false (do not exist, or invalid file name)
        :rtype bool
        """
        # Validate input
        if not isinstance(file_name, str) or not file_name:
            return False
        try:
            return os.path.exists(file_name)
        except Exception:
            return False

def _getTargetClass(self):
    """Define this to return the implementation in use,
    without the 'Py' or 'Fallback' suffix."""
    name = self.__class__.__name__
    # Remove 'Fallback' suffix first if present
    if name.endswith('Fallback'):
        name = name[:-8]
    elif name.endswith('Py'):
        name = name[:-2]
    return name

def directlyProvidedBy(object):  # pylint:disable=redefined-builtin
    """Return the interfaces directly provided by the given object

    The value returned is an `~zope.interface.interfaces.IDeclaration`.
    """
    if object is None:
        raise ValueError("object cannot be None")

    try:
        from zope.interface import directlyProvidedBy as _directlyProvidedBy
    except Exception as exc:
        raise RuntimeError(
            "zope.interface is required to determine directly provided interfaces"
        ) from exc

    try:
        return _directlyProvidedBy(object)
    except Exception as exc:
        raise RuntimeError(
            f"Failed to retrieve directly provided interfaces for {object!r}"
        ) from exc

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    if classes is None:
        return []
    try:
        iterator = iter(classes)
    except TypeError:
        raise TypeError("minimalBases expects an iterable of classes")
    result = []
    for cls in iterator:
        # Skip non-class objects
        if not isinstance(cls, type):
            continue
        # Skip if already covered by an existing base
        if any(issubclass(cls, existing) for existing in result):
            continue
        # Remove any existing bases that are subclasses of the new one
        result = [existing for existing in result if not issubclass(existing, cls)]
        result.append(cls)
    return result

def namesAndDescriptions(self, all=False):  # pylint:disable=redefined-builtin
    """Return attribute names and descriptions defined by interface."""
    if not isinstance(all, bool):
        raise TypeError("Parameter 'all' must be a boolean")
    result = {}
    # Walk the class hierarchy from base to subclass so that subclass
    # definitions override parent ones.
    for cls in reversed(self.__class__.mro()):
        attrs = getattr(cls, "ATTRIBS", None)
        if not isinstance(attrs, dict):
            continue
        for name, attrib in attrs.items():
            # Include the attribute if 'all' is True or if it is required
            # or has a default value.
            include = all
            if not include:
                include = getattr(attrib, "required", False) or getattr(attrib, "default", None) is not None
            if include:
                # Use the description attribute if present, otherwise an empty string.
                description = getattr(attrib, "description", "")
                result[name] = description
    return result

def names(self, all=False):  # pylint:disable=redefined-builtin
    """Return the attribute names defined by the interface."""
    if not isinstance(all, bool):
        raise TypeError("`all` must be a boolean value")
    # Helper to collect interface keys from a class
    def _collect(cls):
        interface = getattr(cls, "INTERFACE", None)
        if isinstance(interface, dict):
            return set(interface.keys())
        return set()

    if all:
        # Gather keys from the entire MRO chain
        attrs = set()
        for cls in self.__class__.mro():
            attrs.update(_collect(cls))
        return sorted(attrs)
    else:
        # Only the direct class's interface
        return sorted(_collect(self.__class__))

def _c_optimizations_ignored():
    """The opposite of `_c_optimizations_required`."""
    try:
        return not _c_optimizations_required()
    except Exception as e:
        raise RuntimeError("Unable to determine if optimizations are ignored: " + str(e))

def reset(self):
    """Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value*
    or with *make_bins()* (depending on the initialization).
    """
    # Reset the context
    self.context = {}

    # Reinitialize bins
    if getattr(self, 'initial_value', None) is not None:
        # If bins is a dict, set each value to the initial value
        if isinstance(self.bins, dict):
            for key in self.bins:
                self.bins[key] = self.initial_value
        else:
            # Assume bins is a list or other sequence
            try:
                length = len(self.bins)
                self.bins = [self.initial_value] * length
            except Exception:
                # Fallback: create a new list with a single initial value
                self.bins = [self.initial_value]
    else:
        # Use the factory method to create new bins
        try:
            self.bins = self.make_bins()
        except Exception as exc:
            raise RuntimeError("Failed to reinitialize bins: %s" % exc) from exc

def to_csv(self, separator=",", header=None):
    """.. deprecated:: 0.5 in Lena 0.5 to_csv is not used.
          Iterables are converted to tables.

    Convert graph's points to CSV.

    *separator* delimits values, the default is comma.

    *header*, if not ``None``, is the first string of the output
    (new line is added automatically).

    Since a graph can be multidimensional,
    for each point first its coordinate is converted to string
    (separated by *separator*), then each part of its value.

    To convert :class:`Graph` to CSV inside a Lena sequence,
    use :class:`lena.output.ToCSV`.
    """
    # Validate arguments
    if not isinstance(separator, str):
        raise TypeError("separator must be a string")
    if header is not None and not isinstance(header, str):
        raise TypeError("header must be a string or None")

    lines = []

    # Add header if provided
    if header is not None:
        # Ensure header ends with a newline
        lines.append(header.rstrip("\n") + "\n")

    # Retrieve points; raise a clear error if not available
    try:
        points = self.points
    except AttributeError:
        raise AttributeError("Object has no 'points' attribute")

    for point in points:
        # Expect point to be a (coord, value) pair
        if isinstance(point, (list, tuple)) and len(point) == 2:
            coord, value = point
        else:
            # Fallback: treat the whole point as coordinate, no value
            coord, value = point, None

        # Convert coordinate to string
        if isinstance(coord, (list, tuple)):
            coord_str = separator.join(map(str, coord))
        else:
            coord_str = str(coord)

        # Convert value to string
        if value is None:
            value_str = ""
        elif isinstance(value, (list, tuple)) and not isinstance(value, str):
            value_str = separator.join(map(str, value))
        else:
            value_str = str(value)

        # Build the line
        line = coord_str
        if value_str:
            line += separator + value_str
        lines.append(line + "\n")

    return "".join(lines)

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    if not isinstance(coord_name, str):
        raise TypeError("coord_name must be a string")
    # Try to locate the error container on the instance
    errors = getattr(self, "errors", None) or getattr(self, "_errors", None)
    if not errors:
        return []
    # If errors is a mapping from coordinate names to index lists
    if isinstance(errors, dict):
        return list(errors.get(coord_name, []))
    # If errors is a list, it might contain tuples or objects
    if isinstance(errors, list):
        # List of (coord, index) tuples
        if all(isinstance(e, tuple) and len(e) == 2 for e in errors):
            return [idx for c, idx in errors if c == coord_name]
        # List of objects with .coord and .index attributes
        return [e.index for e in errors if getattr(e, "coord", None) == coord_name]
    # Fallback: no recognizable structure
    return []

def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    # Basic validation
    try:
        bins = list(bins)
        edges = list(edges)
    except TypeError:
        raise TypeError("bins and edges must be iterable")

    if len(edges) != len(bins) + 1:
        raise ValueError("edges length must be one more than bins length")

    total = 0.0
    for count, left, right in zip(bins, edges, edges[1:]):
        try:
            width = float(right) - float(left)
            total += float(count) * width
        except Exception as exc:
            raise ValueError(f"Invalid numeric values in bins or edges: {exc}") from exc

    return total

def is_fill_request_el(obj):
    """Object contains executable methods 'fill' and 'request'."""
    try:
        return callable(getattr(obj, 'fill', None)) and callable(getattr(obj, 'request', None))
    except Exception:
        return False

def is_run_el(obj):
    """Object contains executable method 'run'."""
    try:
        return callable(getattr(obj, 'run', None))
    except Exception:
        return False

def is_fill_compute_el(obj):
    """Object contains executable methods 'fill' and 'compute'."""
    try:
        return (
            hasattr(obj, 'fill') and callable(getattr(obj, 'fill', None)) and
            hasattr(obj, 'compute') and callable(getattr(obj, 'compute', None))
        )
    except Exception:
        return False

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    # Validate weight
    try:
        weight = float(weight)
    except Exception as exc:
        raise TypeError(f"Weight must be a numeric value, got {type(weight).__name__}") from exc

    # Ensure histogram has edges and data
    if not hasattr(self, "edges") or not hasattr(self, "data"):
        raise AttributeError("Histogram object must have 'edges' and 'data' attributes")

    # Find the bin index for the coordinate
    bin_index = None
    for i in range(len(self.edges) - 1):
        low = self.edges[i]
        high = self.edges[i + 1]
        if low <= coord < high:
            bin_index = i
            break

    # If coordinate is outside the histogram range, ignore it
    if bin_index is None:
        return

    # Increment the bin count by the weight
    try:
        self.data[bin_index] += weight
    except Exception as exc:
        raise RuntimeError(f"Failed to update histogram bin {bin_index}") from exc

    # Keep track of total weight if the attribute exists
    if hasattr(self, "total_weight"):
        try:
            self.total_weight += weight
        except Exception:
            # If total_weight is not numeric, reinitialize
            self.total_weight = weight
    else:
        self.total_weight = weight

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.

            .. code:: python

                # Example:
                labels = {
                    "key1": "valid",
                    "key2": ["invalid"],
                    "$$": "invalid",
                    True: True,
                }
                try:
                    _validate_labels(labels)
                except ValidationError as err:
                    assert err.messages == [
                        {"['invalid']": 'expected string or bytes-like object'},
                        {'$$': "Label key '$$' does not match the regex [...]"},
                        {'True': 'expected string or bytes-like object'},
                        {'True': 'expected string or bytes-like object'},
                    ]
    """
    import re
    # Regular expressions for keys and values. These should be defined elsewhere
    # in the module; if not, fall back to simple defaults.
    try:
        key_regex = LABEL_KEY_REGEX
    except NameError:
        key_regex = r'^[A-Za-z0-9_-]+$'
    try:
        value_regex = LABEL_VALUE_REGEX
    except NameError:
        value_regex = r'^[A-Za-z0-9_-]+$'

    errors = []

    for key, value in labels.items():
        # Validate key
        if not isinstance(key, str):
            errors.append({str(key): 'expected string or bytes-like object'})
        else:
            if not re.match(key_regex, key):
                errors.append({key: f"Label key '{key}' does not match the regex {key_regex}"})

        # Validate value
        if isinstance(value, str):
            if not re.match(value_regex, value):
                errors.append({value: f"Label value '{value}' does not match the regex {value_regex}"})
        elif isinstance(value, list):
            for item in value:
                if not isinstance(item, str):
                    errors.append({str(item): 'expected string or bytes-like object'})
                else:
                    if not re.match(value_regex, item):
                        errors.append({item: f"Label value '{item}' does not match the regex {value_regex}"})
        else:
            errors.append({str(value): 'expected string or bytes-like object'})

    if errors:
        raise ValidationError(messages=errors)

def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:``update_last_applied_manifest_dict_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (list): partial ``last_applied_manifest`` being
            updated
        observer_schema (list): partial ``observer_schema``
        response (list): partial response from the Kubernetes API.

    This function go through all observed fields, and initialized their value in
    last_applied_manifest if they are not yet present

    """
    # Basic validation
    if not isinstance(observer_schema, list):
        raise TypeError("observer_schema must be a list")
    if not isinstance(response, (dict, list)):
        raise TypeError("response must be a dict or list")
    if not isinstance(last_applied_manifest, dict):
        # The function is designed for dict-like structures; raise if not
        raise TypeError("last_applied_manifest must be a dict")

    # If the response itself is a list, recurse into each element
    if isinstance(response, list):
        if not isinstance(last_applied_manifest, list):
            raise TypeError("last_applied_manifest must be a list when response is a list")
        for idx, resp_item in enumerate(response):
            # Ensure the corresponding element exists
            if idx >= len(last_applied_manifest):
                last_applied_manifest.append({})
            update_last_applied_manifest_list_from_resp(
                last_applied_manifest[idx], observer_schema, resp_item
            )
        return

    # At this point, response is a dict
    for field in observer_schema:
        if not isinstance(field, dict):
            continue
        name = field.get("name")
        if not name:
            continue

        # Initialize the field if it is missing in the manifest
        if name not in last_applied_manifest and name in response:
            last_applied_manifest[name] = response[name]

        # Handle nested structures
        subschema = field.get("subschema")
        if not subschema:
            continue

        # Nested list
        if isinstance(response.get(name), list):
            if name not in last_applied_manifest or not isinstance(last_applied_manifest[name], list):
                last_applied_manifest[name] = []
            for idx, item in enumerate(response[name]):
                if idx >= len(last_applied_manifest[name]):
                    last_applied_manifest[name].append({})
                update_last_applied_manifest_list_from_resp(
                    last_applied_manifest[name][idx], subschema, item
                )
        # Nested dict
        elif isinstance(response.get(name), dict):
            if name not in last_applied_manifest or not isinstance(last_applied_manifest[name], dict):
                last_applied_manifest[name] = {}
            update_last_applied_manifest_list_from_resp(
                last_applied_manifest[name], subschema, response[name]
            )

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Basic validation of the input object
    if app is None:
        raise TypeError("app must not be None")

    # Try to access the manifest dictionary
    try:
        spec = getattr(app, "spec", None)
        if spec is None:
            raise AttributeError("Application object has no 'spec' attribute")
        manifest = getattr(spec, "manifest", None)
        if manifest is None:
            raise AttributeError("Application spec has no 'manifest' attribute")
        if not isinstance(manifest, dict):
            raise TypeError("Application spec.manifest must be a dictionary")
    except Exception as exc:
        raise ValueError(f"Invalid application object: {exc}") from exc

    # Iterate over each resource in the manifest
    for resource_name, resource_def in manifest.items():
        # Skip non-dict definitions
        if not isinstance(resource_def, dict):
            continue

        # Skip if a custom observer schema is already defined
        if "observer_schema" in resource_def and resource_def["observer_schema"] is not None:
            continue

        # Create a simple default observer schema
        default_schema = {
            "type": "object",
            "properties": {
                "metadata": {"type": "object"},
                "spec": {"type": "object"},
                "status": {"type": "object"},
            },
            "required": ["metadata", "spec"],
        }

        # Attach the default schema to the resource definition
        resource_def["observer_schema"] = default_schema

    # The function modifies the application in place; return None for clarity
    return None

def status_str(self, prefix=''):
    """Return string of validator status, with optional prefix."""
    # Try to obtain the status attribute from the object
    status = getattr(self, 'status', None)
    if status is None:
        status = getattr(self, 'validator_status', None)
    if status is None:
        # No status information available
        return prefix

    # Convert the status to a readable string
    if isinstance(status, (list, tuple)):
        status_text = ', '.join(str(item) for item in status)
    elif isinstance(status, dict):
        status_text = ', '.join(f'{k}: {v}' for k, v in status.items())
    elif isinstance(status, bool):
        status_text = 'OK' if status else 'FAIL'
    else:
        status_text = str(status)

    return f'{prefix}{status_text}'

def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    if not isinstance(prefix, str):
        raise TypeError("prefix must be a string")
    try:
        log = getattr(self, 'validation_log', None)
        if not log:
            return ''
        lines = []
        if isinstance(log, dict):
            for key, value in log.items():
                lines.append(f"{prefix}{key}: {value}")
        elif isinstance(log, (list, tuple)):
            for item in log:
                if isinstance(item, (list, tuple)) and len(item) == 2:
                    key, value = item
                    lines.append(f"{prefix}{key}: {value}")
                else:
                    lines.append(f"{prefix}{item}")
        else:
            lines.append(f"{prefix}{log}")
        return "\n".join(lines)
    except Exception as exc:
        return f"{prefix}Error generating status string: {exc}"

def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    # Basic type checks
    if not isinstance(inventory, dict):
        raise TypeError("inventory must be a dict")

    # Determine spec version
    spec_version = getattr(self, "spec_version", None)
    if extract_spec_version:
        type_val = inventory.get("type")
        if isinstance(type_val, str):
            # Assume a simple format like "spec-<version>"
            parts = type_val.split("-")
            if len(parts) >= 2:
                try:
                    spec_version = parts[-1]
                except Exception:
                    pass
        # If type missing or invalid, keep self.spec_version

    # Example validation: inventory must contain an 'items' key
    if "items" not in inventory:
        raise ValueError("inventory missing required 'items' key")

    items = inventory["items"]
    if not isinstance(items, list):
        raise TypeError("'items' must be a list")

    # Validate each item is a dict with required keys
    for idx, item in enumerate(items):
        if not isinstance(item, dict):
            raise TypeError(f"item at index {idx} is not a dict")
        if "id" not in item:
            raise ValueError(f"item at index {idx} missing 'id'")
        if "value" not in item:
            raise ValueError(f"item at index {idx} missing 'value'")

    # Additional checks based on spec_version could be added here
    # For now, just return True if all checks pass
    return True

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Ensure prior is an instance of the same class
    if not isinstance(prior, type(self)):
        raise TypeError(f"prior must be an instance of {type(self).__name__}, got {type(prior).__name__}")

    # Check that required attributes exist
    required_attrs = ['version', 'id', 'items']
    for attr in required_attrs:
        if not hasattr(self, attr):
            raise AttributeError(f"Current inventory object is missing required attribute '{attr}'")
        if not hasattr(prior, attr):
            raise AttributeError(f"Prior inventory object is missing required attribute '{attr}'")

    # Compare versions: prior must be older
    try:
        if prior.version >= self.version:
            raise ValueError(f"Prior version ({prior.version}) is not older than current version ({self.version})")
    except Exception as exc:
        raise ValueError(f"Error comparing versions: {exc}") from exc

    # Compare IDs: must match
    if prior.id != self.id:
        raise ValueError(f"Prior inventory id ({prior.id}) does not match current id ({self.id})")

    # Compare items: prior items must be a subset of current items
    try:
        # Convert to sets if possible
        current_items = set(self.items)
        prior_items = set(prior.items)
    except Exception as exc:
        raise ValueError(f"Error converting items to sets: {exc}") from exc

    if not prior_items.issubset(current_items):
        missing = prior_items - current_items
        raise ValueError(f"Prior inventory contains items not present in current inventory: {missing}")

    # All checks passed
    return True

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    if not isinstance(inventory, (dict, list)):
        raise TypeError("inventory must be a dict or list")

    result = {}

    def add_file(logical_path, content_file):
        if logical_path not in result:
            result[logical_path] = set()
        result[logical_path].add(content_file)

    try:
        if isinstance(inventory, dict):
            for logical_path, entries in inventory.items():
                if isinstance(entries, list):
                    for entry in entries:
                        if not isinstance(entry, dict):
                            continue
                        ver = entry.get("version")
                        file = entry.get("content_file")
                        if ver is None or file is None:
                            continue
                        try:
                            if ver >= version:
                                add_file(logical_path, file)
                        except Exception:
                            # skip if version comparison fails
                            continue
                elif isinstance(entries, dict):
                    ver = entries.get("version")
                    file = entries.get("content_file")
                    if ver is not None and file is not None:
                        try:
                            if ver >= version:
                                add_file(logical_path, file)
                        except Exception:
                            continue
                else:
                    # treat the entry itself as a file
                    add_file(logical_path, entries)
        else:  # inventory is a list
            for entry in inventory:
                if not isinstance(entry, dict):
                    continue
                logical_path = entry.get("logical_path")
                ver = entry.get("version")
                file = entry.get("content_file")
                if logical_path is None or ver is None or file is None:
                    continue
                try:
                    if ver >= version:
                        add_file(logical_path, file)
                except Exception:
                    continue
    except Exception as exc:
        raise RuntimeError(f"Failed to build logical path map: {exc}") from exc

    return result

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Basic type checks
    if fixity is None:
        raise ValueError("fixity block cannot be None")
    if not isinstance(fixity, dict):
        raise TypeError(f"fixity must be a dict, got {type(fixity).__name__}")

    if manifest_files is None:
        raise ValueError("manifest_files cannot be None")
    if not isinstance(manifest_files, (set, list, tuple)):
        raise TypeError(f"manifest_files must be a set, list, or tuple, got {type(manifest_files).__name__}")

    # Ensure manifest_files is a set for fast lookup
    manifest_set = set(manifest_files)

    # Required keys in a fixity block
    required_keys = {"file", "hash", "algorithm"}
    missing_keys = required_keys - fixity.keys()
    if missing_keys:
        raise ValueError(f"Missing required keys in fixity block: {missing_keys}")

    # Validate file reference
    file_ref = fixity["file"]
    if not isinstance(file_ref, str):
        raise TypeError(f"file reference must be a string, got {type(file_ref).__name__}")
    if file_ref not in manifest_set:
        raise ValueError(f"Fixity block references unknown file '{file_ref}' not present in the manifest")

    # Validate hash value
    hash_val = fixity["hash"]
    if not isinstance(hash_val, str):
        raise TypeError(f"hash value must be a string, got {type(hash_val).__name__}")

    # Validate algorithm
    algorithm = fixity["algorithm"]
    if not isinstance(algorithm, str):
        raise TypeError(f"algorithm must be a string, got {type(algorithm).__name__}")
    supported_algorithms = {"sha256", "sha1", "md5"}
    if algorithm.lower() not in supported_algorithms:
        raise ValueError(f"Unsupported hash algorithm '{algorithm}'. Supported algorithms: {supported_algorithms}")

    # Optional: basic hex string check for hash length
    if algorithm.lower() == "sha256" and len(hash_val) != 64:
        raise ValueError("SHA-256 hash must be 64 hex characters long")
    if algorithm.lower() == "sha1" and len(hash_val) != 40:
        raise ValueError("SHA-1 hash must be 40 hex characters long")
    if algorithm.lower() == "md5" and len(hash_val) != 32:
        raise ValueError("MD5 hash must be 32 hex characters long")

    # If all checks pass, return True
    return True

def files_list(path):
    """Return the files in `path`."""
    import os
    if not isinstance(path, (str, bytes)):
        raise TypeError("path must be a string or bytes")
    if not os.path.exists(path):
        raise FileNotFoundError(f"Path does not exist: {path}")
    if not os.path.isdir(path):
        raise NotADirectoryError(f"Path is not a directory: {path}")
    try:
        entries = os.listdir(path)
    except OSError as e:
        raise OSError(f"Error listing directory {path}: {e}") from e
    files = []
    for entry in entries:
        full = os.path.join(path, entry)
        if os.path.isfile(full):
            files.append(entry)
    return files

def _eval_file(prefix, file_path):
    """Identifica o tipo de arquivo do pacote: `asset` ou `rendition`.

    Identifica o tipo de arquivo do pacote e atualiza `packages` com o tipo e
    o endereço do arquivo em análise.

    Parameters
    ----------
    prefix : str
        nome do arquivo XML sem extensão
    file_path : str
        caminho completo do arquivo

    Returns
    -------
    dict
    """
    # Validate input types
    if not isinstance(prefix, str):
        raise TypeError("prefix must be a string")
    if not isinstance(file_path, str):
        raise TypeError("file_path must be a string")

    # Ensure the file exists
    if not os.path.exists(file_path):
        raise FileNotFoundError(f"File not found: {file_path}")

    # Heuristic to determine the file type
    lower_path = file_path.lower()
    if "asset" in lower_path:
        file_type = "asset"
    elif "rendition" in lower_path:
        file_type = "rendition"
    else:
        # Fallback: try to inspect the XML root element
        try:
            tree = ET.parse(file_path)
            root = tree.getroot()
            tag = root.tag.lower()
            if "asset" in tag:
                file_type = "asset"
            elif "rendition" in tag:
                file_type = "rendition"
            else:
                file_type = "unknown"
        except Exception:
            file_type = "unknown"

    return {"type": file_type, "path": file_path}

def add_rendition(self, lang, file_path):
    """
    {
        "original": "artigo02.pdf",
        "en": "artigo02-en.pdf",
    }
    """
    # Validate language code
    if not isinstance(lang, str) or not lang.strip():
        raise ValueError("lang must be a non-empty string")

    # Validate file path
    if not isinstance(file_path, str) or not file_path.strip():
        raise ValueError("file_path must be a non-empty string")

    # Ensure the renditions container exists
    if not hasattr(self, "renditions") or not isinstance(self.renditions, dict):
        self.renditions = {}

    # Add or overwrite the rendition for the given language
    self.renditions[lang] = file_path

    # Return the stored path for convenience
    return self.renditions[lang]

def add_asset(self, basename, file_path):
    """
    "{
        "artigo02-gf03.tiff": "/path/artigo02-gf03.tiff",
        "artigo02-gf03.jpg": "/path/artigo02-gf03.jpg",
        "artigo02-gf03.png": "/path/artigo02-gf03.png",
    }
    """
    import os

    # Validate input types
    if not isinstance(basename, str):
        raise TypeError(f"basename must be a string, got {type(basename).__name__}")
    if not isinstance(file_path, str):
        raise TypeError(f"file_path must be a string, got {type(file_path).__name__}")

    # Ensure the file exists
    if not os.path.isfile(file_path):
        raise FileNotFoundError(f"File not found: {file_path}")

    # Initialize the assets dictionary if it doesn't exist
    if not hasattr(self, "assets") or not isinstance(self.assets, dict):
        self.assets = {}

    # Check for duplicate basename
    if basename in self.assets:
        raise ValueError(f"An asset with basename '{basename}' already exists.")

    # Add the asset
    self.assets[basename] = file_path
    return None

def _explore_zipfile(zip_path):
    """
    Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    import os
    import zipfile

    if not isinstance(zip_path, str):
        raise TypeError("zip_path must be a string path to a zip file")

    if not os.path.isfile(zip_path):
        raise FileNotFoundError(f"Zip file not found: {zip_path}")

    packages = {}

    try:
        with zipfile.ZipFile(zip_path, 'r') as zf:
            for name in zf.namelist():
                # Skip directories
                if name.endswith('/'):
                    continue

                # Get the base name without extension
                base = os.path.splitext(os.path.basename(name))[0]

                # Initialize package entry if not present
                if base not in packages:
                    packages[base] = {'xml': None, 'files': []}

                # If the file is an XML file, read its content
                if name.lower().endswith('.xml'):
                    try:
                        with zf.open(name) as f:
                            packages[base]['xml'] = f.read().decode('utf-8')
                    except Exception as exc:
                        # If reading fails, store None and log the error
                        packages[base]['xml'] = None
                        # Optionally, you could log the exception here
                else:
                    # For non-XML files, just store the file name
                    packages[base]['files'].append(name)

    except zipfile.BadZipFile as exc:
        raise zipfile.BadZipFile(f"Invalid zip file: {zip_path}") from exc
    except Exception as exc:
        # Re-raise any other exception with context
        raise RuntimeError(f"Error processing zip file {zip_path}") from exc

