def pretty(self, indent=0, debug=False):
    """Return a pretty formatted representation of self."""
    try:
        if not isinstance(indent, int):
            raise TypeError("indent must be an integer")
        indent_str = '    ' * indent
        parts = [f"{indent_str}{self.__class__.__name__}"]
        if debug:
            parts.append(f" (id={getattr(self, 'id', None)})")
        # Include non-private attributes
        attrs = []
        for k, v in self.__dict__.items():
            if k.startswith('_'):
                continue
            attrs.append(f"{k}={v!r}")
        if attrs:
            parts.append(f" [{', '.join(attrs)}]")
        # Recursively pretty-print children if iterable
        if hasattr(self, '__iter__'):
            child_strs = []
            for child in self:
                if hasattr(child, 'pretty') and callable(child.pretty):
                    child_strs.append(child.pretty(indent + 1, debug))
                else:
                    child_strs.append('    ' * (indent + 1) + repr(child))
            if child_strs:
                parts.append('\n' + '\n'.join(child_strs))
        return ''.join(parts)
    except Exception as e:
        return f"<Error pretty: {e}>"

