def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    if not callable(namefunc):
        raise TypeError("tzname_in_python2 expects a callable, got %r" % (namefunc,))
    import sys
    import functools
    @functools.wraps(namefunc)
    def wrapper(*args, **kwargs):
        try:
            result = namefunc(*args, **kwargs)
        except Exception:
            raise
        if sys.version_info[0] < 3:
            if isinstance(result, unicode):
                try:
                    return result.encode('utf-8')
                except Exception as e:
                    raise ValueError("Failed to encode unicode result to bytestring: %s" % e)
        return result
    return wrapper

def get_versions():
    """Get version information or return default if unable to do so."""
    # Attempt to import the standard library metadata module
    try:
        from importlib.metadata import version, PackageNotFoundError
    except ImportError:
        # Fallback for older Python versions
        try:
            from importlib_metadata import version, PackageNotFoundError  # type: ignore
        except ImportError:
            return {
                'version': '0+unknown',
                'full-revisionid': None,
                'dirty': False,
                'error': 'importlib.metadata not available',
            }

    # Determine the top‑level package name from the current module
    package_name = __name__.split('.')[0] if __name__ else None

    if not package_name:
        return {
            'version': '0+unknown',
            'full-revisionid': None,
            'dirty': False,
            'error': 'unable to determine package name',
        }

    try:
        ver = version(package_name)
    except PackageNotFoundError as exc:
        return {
            'version': '0+unknown',
            'full-revisionid': None,
            'dirty': False,
            'error': str(exc),
        }
    except Exception as exc:
        return {
            'version': '0+unknown',
            'full-revisionid': None,
            'dirty': False,
            'error': f'unexpected error: {exc}',
        }

    # The metadata API does not provide git revision or dirty flag,
    # so we return None/False for those fields.
    return {
        'version': ver,
        'full-revisionid': None,
        'dirty': False,
        'error': None,
    }

def render(pieces, style):
    """Render the given version pieces into the requested style."""
    # Validate pieces
    if pieces is None:
        return ''
    try:
        iterator = iter(pieces)
    except TypeError:
        raise TypeError("pieces must be an iterable")

    # Normalise style
    if style is None:
        style = 'text'
    if not isinstance(style, str):
        raise TypeError("style must be a string")
    style = style.lower()

    # Supported styles
    supported = {'text', 'html', 'json'}
    if style not in supported:
        raise ValueError(f"Unsupported style: {style!r}")

    rendered_parts = []
    for p in pieces:
        # If the piece has a render method, try to use it
        if hasattr(p, 'render') and callable(p.render):
            try:
                rendered_parts.append(p.render(style))
                continue
            except Exception:
                # Fall back to string representation
                pass
        # Default: convert to string
        rendered_parts.append(str(p))

    if style == 'text':
        # Join with spaces for readability
        return ' '.join(rendered_parts)
    elif style == 'html':
        # Wrap each part in a span for simple HTML rendering
        return ''.join(f'<span>{part}</span>' for part in rendered_parts)
    elif style == 'json':
        # Return a JSON array of the rendered parts
        import json
        return json.dumps(rendered_parts)
    # Fallback (should not be reached)
    return ''.join(rendered_parts)

def plus_or_dot(pieces):
    """Return a + if we don't already have one, else return a ."""
    try:
        for piece in pieces:
            try:
                if '+' in piece:
                    return '.'
            except TypeError:
                if piece == '+':
                    return '.'
    except TypeError:
        # pieces is not iterable
        pass
    return '+'

def register_vcs_handler(vcs, method=None):
    """Create decorator to mark a method as the handler of a VCS."""
    if not isinstance(vcs, str):
        raise TypeError("vcs must be a string")
    if method is None:
        # decorator form: @register_vcs_handler('git')
        def decorator(func):
            return register_vcs_handler(vcs, func)
        return decorator
    if not callable(method):
        raise TypeError("method must be callable")
    # maintain a registry of handlers
    if not hasattr(register_vcs_handler, "_registry"):
        register_vcs_handler._registry = {}
    registry = register_vcs_handler._registry
    if vcs in registry:
        raise ValueError(f"Handler for VCS '{vcs}' is already registered")
    registry[vcs] = method
    return method

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    # Validate input types
    if not isinstance(validate_objects, bool):
        raise TypeError("validate_objects must be a bool")
    if not isinstance(check_digests, bool):
        raise TypeError("check_digests must be a bool")
    if not isinstance(show_warnings, bool):
        raise TypeError("show_warnings must be a bool")

    num_objects = 0
    good_objects = 0

    def _validate(obj):
        nonlocal num_objects, good_objects
        num_objects += 1
        is_valid = True

        # Validate the object itself if requested
        if validate_objects:
            try:
                if hasattr(obj, "validate"):
                    # Assume validate() returns a bool or raises an exception
                    result = obj.validate()
                    if result is False:
                        is_valid = False
                # If no validate method, assume valid
            except Exception as exc:
                is_valid = False
                if show_warnings:
                    print(f"Warning: validation error for {obj.__class__.__name__} (id={getattr(obj, 'id', None)}): {exc}")

        # Check digests if requested
        if check_digests:
            try:
                if hasattr(obj, "check_digest"):
                    result = obj.check_digest()
                    if result is False:
                        is_valid = False
                # If no check_digest method, assume valid
            except Exception as exc:
                is_valid = False
                if show_warnings:
                    print(f"Warning: digest check error for {obj.__class__.__name__} (id={getattr(obj, 'id', None)}): {exc}")

        if is_valid:
            good_objects += 1

        # Recurse into children if the object is iterable
        try:
            for child in obj:
                _validate(child)
        except TypeError:
            # Object is not iterable; nothing to recurse into
            pass

    # Start validation from the root object
    _validate(self)

    return num_objects, good_objects

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not isinstance(version, str) or not version:
        raise ValueError("Version must be a non-empty string")

    def _increment(part):
        if not part.isdigit():
            raise ValueError(f"Invalid numeric part in version: '{part}'")
        width = len(part)
        new_num = int(part) + 1
        # Preserve leading zeros if any
        return str(new_num).zfill(width)

    try:
        if '.' in version:
            parts = version.split('.')
            parts[-1] = _increment(parts[-1])
            return '.'.join(parts)
        else:
            return _increment(version)
    except ValueError as exc:
        raise ValueError(f"Cannot compute next version for '{version}': {exc}") from exc

