    """Amend the Bugzilla params"""
    # Validate params
    if not isinstance(params, dict):
        raise TypeError("params must be a dict")
    # Nothing to do if no bug ids supplied
    if bug_ids is None:
        return
    # Normalize bug_ids to a list of strings
    if isinstance(bug_ids, (int, str)):
        bug_ids_list = [str(bug_ids)]
    elif isinstance(bug_ids, (list, tuple, set)):
        bug_ids_list = [str(b) for b in bug_ids]
    else:
        raise TypeError("bug_ids must be an int, str, list, tuple, or set")
    # Convert to comma‑separated string
    bug_ids_str = ",".join(bug_ids_list)
    # Merge with existing 'ids' if present
    if "ids" in params:
        # Existing ids may be a string or a list
        existing = params["ids"]
        if isinstance(existing, (list, tuple, set)):
            existing_list = [str(e) for e in existing]
        else:
            existing_list = [e for e in str(existing).split(",") if e]
        # Combine unique ids
        combined = sorted(set(existing_list) | set(bug_ids_list), key=lambda x: int(x) if x.isdigit() else x)
        params["ids"] = ",".join(combined)
    else:
        # No existing ids, just set
        params["ids"] = bug_ids_str
    # If a single bug id was supplied and the caller used the key 'bug_id',
    # replace it with the unified 'ids' key for consistency
    if "bug_id" in params:
        del params["bug_id"]

