    # Generate pages
    for i in range(0, len(response), max_results):
        yield response[i:i + max_results]

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    if dicts is None:
        return {}
    try:
        iterator = iter(dicts)
    except TypeError:
        raise TypeError("Expected an iterable of dictionaries") from None

    result = {}
    for d in iterator:
        if not isinstance(d, dict):
            raise TypeError(f"Expected dict, got {type(d).__name__}")
        for key, value in d.items():
            result[key] = result.get(key, 0) + value
    return result

