def is_none_string(val: any) -> bool:
    """Check if a string represents a None value."""
    # Direct None is considered a None value
    if val is None:
        return True

    # Only strings can represent a textual None value
    if isinstance(val, str):
        # Normalize by stripping whitespace and converting to lower case
        s = val.strip().lower()
        # Common textual representations of None
        return s in {"none", "null", "nan", "n/a"}

    # All other types are not considered None strings
    return False

