def regex_dict(item):
    """
    Convert *.cpp keys to regex keys

    Given a dict where the keys are all filenames with wildcards, convert only
    the keys into equivalent regexes and leave the values intact.

    Example:

    rules = {
        '*.cpp':
            {'a': 'arf', 'b': 'bark', 'c': 'coo'},
        '*.h':
            {'h': 'help'}
    }
    regex_keys = regex_dict(rules)

    Args:
        item: dict to convert
    Returns:
        dict with keys converted to regexes
    """
    if not isinstance(item, dict):
        raise TypeError("Expected a dictionary for 'item'")
    result = {}
    for key, value in item.items():
        if not isinstance(key, str):
            raise TypeError("Dictionary keys must be strings")
        if '*' in key:
            # Escape all regex special characters except '*'
            parts = key.split('*')
            escaped_parts = [re.escape(part) for part in parts]
            regex_key = '^' + '.*'.join(escaped_parts) + '$'
            result[regex_key] = value
        else:
            result[key] = value
    return result

def unquote(name):
    """Remove quote from the given name."""
    if name is None:
        return None
    if not isinstance(name, str):
        return name
    # Match a string that starts and ends with the same quote character
    m = re.match(r"^(['\"])(.*)\1$", name)
    if m:
        return m.group(2)
    return name

