                token = ''
                i = 0
                while i < len(raw):
                    if raw[i] == '\\':
                        # Count consecutive backslashes
                        bs = 0
                        while i < len(raw) and raw[i] == '\\':
                            bs += 1
                            i += 1
                        if i < len(raw) and raw[i] == '"':
                            # Escape quote
                            token += '\\' * (bs // 2)
                            if bs % 2 == 1:
                                token += '"'
                            i += 1
                        else:
                            token += '\\' * bs
                    else:
                        token += raw[i]
                        i += 1
                args.append(token)
            else:
                args.append(m.group(2))
        return args

    else:
        raise ValueError(f"Unsupported platform value: {platform}")

def addignored(ignored):
    """Use the git command to obtain the file names, turn it into a list, sort the list for only ignored files, return those files as a single string with each filename separated by a comma."""
    try:
        output = subprocess.check_output(
            ['git', 'ls-files', '--others', '--ignored', '--exclude-standard'],
            stderr=subprocess.STDOUT,
            text=True
        )
    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"Git command failed: {e.output}") from e
    except FileNotFoundError as e:
        raise RuntimeError("Git is not installed or not found in PATH") from e

    files = output.splitlines()
    # The command already returns only ignored files, but if a filter list is provided, apply it
    if ignored:
        try:
            ignored_set = set(ignored)
        except TypeError:
            raise TypeError("ignored must be an iterable of filenames") from None
        files = [f for f in files if f in ignored_set]
    files.sort()
    return ','.join(files)

def is_local(host):
    """Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    if not isinstance(host, str):
        raise TypeError("host must be a string")
    host = host.strip()
    if not host:
        return False
    if host.lower() == 'localhost':
        return True
    if host == '127.0.0.1':
        return True
    if host == '::1':
        return True
    try:
        for res in socket.getaddrinfo(host, None):
            family, _, _, _, sockaddr = res
            addr = sockaddr[0]
            if family == socket.AF_INET:
                if addr.startswith('127.'):
                    return True
            elif family == socket.AF_INET6:
                if addr == '::1':
                    return True
    except socket.gaierror:
        return False
    return False

def is_gitbash():
    """returns True if you run in a Windows gitbash

    :return: True if gitbash
    """
    try:
        ostype = os.getenv('OSTYPE', '').lower()
        msystem = os.getenv('MSYSTEM', '').lower()
        if 'msys' in ostype or 'cygwin' in ostype:
            return True
        if msystem in ('mingw32', 'mingw64', 'msys'):
            return True
        term_program = os.getenv('TERM_PROGRAM', '').lower()
        if term_program == 'mintty':
            return True
    except Exception:
        pass
    return False

def write_configuration(config_filename, rendered_config, mode=0o600, overwrite=False):
    '''
    Given a target config filename and rendered config YAML, write it out to file. Create any
    containing directories as needed. But if the file already exists and overwrite is False,
    abort before writing anything.
    '''
    # Validate inputs
    if not isinstance(config_filename, str):
        raise TypeError(f"config_filename must be a string, got {type(config_filename).__name__}")
    if not isinstance(rendered_config, str):
        raise TypeError(f"rendered_config must be a string, got {type(rendered_config).__name__}")
    if not isinstance(mode, int):
        raise TypeError(f"mode must be an integer, got {type(mode).__name__}")
    if not isinstance(overwrite, bool):
        raise TypeError(f"overwrite must be a bool, got {type(overwrite).__name__}")

    # Resolve absolute path
    config_path = os.path.abspath(config_filename)
    dir_name = os.path.dirname(config_path)

    # Create directories if needed
    try:
        if dir_name:
            os.makedirs(dir_name, exist_ok=True)
    except Exception as exc:
        raise OSError(f"Failed to create directories for '{config_path}': {exc}") from exc

    # Check for existing file
    if os.path.exists(config_path):
        if not overwrite:
            raise FileExistsError(f"File '{config_path}' already exists and overwrite is False.")
        # If overwrite is True, we will replace the file

    # Write the rendered configuration
    try:
        with open(config_path, 'w', encoding='utf-8') as f:
            f.write(rendered_config)
    except Exception as exc:
        raise OSError(f"Failed to write configuration to '{config_path}': {exc}") from exc

    # Set file permissions
    try:
        os.chmod(config_path, mode)
    except Exception as exc:
        # If chmod fails, we still consider the write successful but warn
        raise OSError(f"Failed to set mode {oct(mode)} on '{config_path}': {exc}") from exc

    return config_path

def _resolve_string(matcher):
    '''
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    '''
    if matcher is None:
        raise ValueError("Matcher cannot be None")
    # Extract variable name
    try:
        name = matcher.group(1)
    except AttributeError:
        raise TypeError("Matcher must have a group method (e.g., a regex match object)")
    if not name:
        raise ValueError("Variable name cannot be empty")
    # Extract default if present
    try:
        default = matcher.group(2)
    except IndexError:
        default = None
    # Get environment value
    value = os.getenv(name)
    if value is not None:
        return value
    if default is not None:
        return default
    raise KeyError(f"Environment variable '{name}' not found and no default provided")

def get_pattern(pattern, strip=True):
    """This method converts the given string to regex pattern"""
    if pattern is None:
        raise ValueError("pattern must not be None")
    if not isinstance(pattern, str):
        raise TypeError("pattern must be a string")
    if strip:
        pattern = pattern.strip()
    # Escape regex special characters
    escaped = re.escape(pattern)
    # Compile the escaped pattern
    try:
        return re.compile(escaped)
    except re.error as e:
        raise ValueError(f"Invalid regex pattern: {escaped}") from e

