            )
    except Exception as exc:
        raise ValueError(f"Failed to dump object to string: {exc}") from exc

def gaussian(x):
    """
    Gaussian centered around 0.2 with a sigma of 0.1.
    """
    try:
        x_arr = np.asarray(x, dtype=float)
    except Exception as e:
        raise TypeError("Input must be a number or array-like of numbers") from e

    mean = 0.2
    sigma = 0.1
    return np.exp(-((x_arr - mean) ** 2) / (2 * sigma ** 2))

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import json
    import configparser
    import os
    import re

    configs = {}
    errors = []

    # Helper to resolve environment variables in strings
    env_pattern = re.compile(r'\$\{([^}]+)\}')

    def resolve_env_in_string(s):
        def repl(match):
            return os.getenv(match.group(1), '')
        return env_pattern.sub(repl, s)

    def resolve_env_in_obj(obj):
        if isinstance(obj, dict):
            return {k: resolve_env_in_obj(v) for k, v in obj.items()}
        elif isinstance(obj, list):
            return [resolve_env_in_obj(v) for v in obj]
        elif isinstance(obj, str):
            return resolve_env_in_string(obj)
        else:
            return obj

    for filename in config_filenames:
        try:
            with open(filename, 'r', encoding='utf-8') as f:
                content = f.read()
        except Exception as e:
            record = logging.LogRecord(
                name='load_configurations',
                level=logging.ERROR,
                pathname=filename,
                lineno=0,
                msg=f'Failed to open file {filename}: {e}',
                args=None,
                exc_info=e
            )
            errors.append(record)
            continue

        parsed = None
        # Try JSON first
        try:
            parsed = json.loads(content)
        except Exception:
            # Try INI/ConfigParser
            try:
                parser = configparser.ConfigParser()
                parser.read_file(f)
                parsed = {section: dict(parser.items(section)) for section in parser.sections()}
            except Exception as e:
                record = logging.LogRecord(
                    name='load_configurations',
                    level=logging.ERROR,
                    pathname=filename,
                    lineno=0,
                    msg=f'Failed to parse file {filename}: {e}',
                    args=None,
                    exc_info=e
                )
                errors.append(record)
                continue

        # Apply overrides if provided
        if overrides and filename in overrides:
            override_dict = overrides[filename]
            if isinstance(parsed, dict) and isinstance(override_dict, dict):
                parsed.update(override_dict)
            else:
                record = logging.LogRecord(
                    name='load_configurations',
                    level=logging.WARNING,
                    pathname=filename,
                    lineno=0,
                    msg=f'Override for {filename} is not a dict; skipping override.',
                    args=None,
                    exc_info=None
                )
                errors.append(record)

        # Resolve environment variables if requested
        if resolve_env:
            try:
                parsed = resolve_env_in_obj(parsed)
            except Exception as e:
                record = logging.LogRecord(
                    name='load_configurations',
                    level=logging.ERROR,
                    pathname=filename,
                    lineno=0,
                    msg=f'Failed to resolve environment variables in {filename}: {e}',
                    args=None,
                    exc_info=e
                )
                errors.append(record)
                continue

        configs[filename] = parsed

    return configs, errors

def force_string(obj):
    """This function returns the bytes object corresponding to ``obj`` in case it is a string using UTF-8."""
    if isinstance(obj, bytes):
        return obj
    if isinstance(obj, str):
        try:
            return obj.encode('utf-8')
        except Exception as e:
            raise ValueError(f"Could not encode string to UTF-8: {e}") from e
    raise TypeError(f"Expected str or bytes, got {type(obj).__name__}")

def from_raw_values(cls, values):
    """Create a Bookmarks object from a list of raw bookmark string values.

    You should not need to use this method unless you want to deserialize
    bookmarks.

    :param values: ASCII string values (raw bookmarks)
    :type values: Iterable[str]
    """
    if values is None:
        raise ValueError("values must be an iterable of strings")

    try:
        instance = cls()
    except Exception as exc:
        raise RuntimeError("Failed to instantiate Bookmarks object") from exc

    for v in values:
        if not isinstance(v, str):
            raise TypeError(f"Bookmark value must be a string, got {type(v).__name__}")
        val = v.strip()
        if not val:
            continue
        try:
            if hasattr(instance, "add") and callable(instance.add):
                instance.add(val)
            else:
                # Fallback: store in a 'bookmarks' attribute
                if not hasattr(instance, "bookmarks"):
                    instance.bookmarks = set()
                instance.bookmarks.add(val)
        except Exception as exc:
            raise RuntimeError(f"Failed to add bookmark '{val}'") from exc

    return instance

def scale(self, other=None):
    """Get or set the scale of the graph.

    If *other* is ``None``, return the scale of this graph.

    If a numeric *other* is provided, rescale to that value.
    If the graph has unknown or zero scale,
    rescaling that will raise :exc:`~.LenaValueError`.

    To get meaningful results, graph's fields are used.
    Only the last coordinate is rescaled.
    For example, if the graph has *x* and *y* coordinates,
    then *y* will be rescaled, and for a 3-dimensional graph
    *z* will be rescaled.
    All errors are rescaled together with their coordinate.
    """
    # Return current scale if no new scale is requested
    if other is None:
        return getattr(self, "scale", None)

    # Validate the new scale
    if not isinstance(other, (int, float)):
        raise TypeError("The 'other' argument must be a numeric value.")
    current_scale = getattr(self, "scale", None)
    if current_scale is None or current_scale == 0:
        raise LenaValueError("Cannot rescale a graph with unknown or zero scale.")

    # Compute the scaling factor
    factor = other / current_scale

    # Rescale the last coordinate in the data
    if hasattr(self, "data"):
        data = self.data
        if isinstance(data, list):
            # Assume each element is a sequence (tuple/list) of coordinates
            for idx, point in enumerate(data):
                if isinstance(point, (list, tuple)) and len(point) > 0:
                    new_point = list(point)
                    new_point[-1] *= factor
                    data[idx] = type(point)(new_point)
        elif isinstance(data, dict):
            # Assume keys are field names and values are lists of values
            if data:
                last_field = list(data.keys())[-1]
                data[last_field] = [v * factor for v in data[last_field]]

    # Rescale the errors associated with the last coordinate
    if hasattr(self, "errors"):
        errors = self.errors
        if isinstance(errors, list):
            for idx, err in enumerate(errors):
                if isinstance(err, (list, tuple)) and len(err) > 0:
                    new_err = list(err)
                    new_err[-1] *= factor
                    errors[idx] = type(err)(new_err)
        elif isinstance(errors, dict):
            if errors:
                last_field = list(errors.keys())[-1]
                errors[last_field] = [e * factor for e in errors[last_field]]

    # Update the scale attribute
    self.scale = other
    return self.scale

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    # Validate bases
    if not bases:
        return type
    for b in bases:
        if not isinstance(b, type):
            raise TypeError(f"Base {b!r} is not a class")
    # Determine metaclasses of bases
    metaclasses = [type(b) for b in bases]
    # If an explicit metaclass is provided, validate it
    if explicit_mc is not None:
        if not isinstance(explicit_mc, type):
            raise TypeError(f"Explicit metaclass {explicit_mc!r} is not a type")
        for mc in metaclasses:
            if not issubclass(explicit_mc, mc):
                raise Type

def pop(self, key, default=__marker):
    """D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised."""
    if key in self:
        value = self[key]
        del self[key]
        return value
    if default is __marker:
        raise KeyError(key)
    return default

def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    if not self:
        raise KeyError('popitem(): dictionary is empty')
    freq = getattr(self, '_freq', None)
    min_key = None
    min_freq = None
    for k in self:
        f = freq.get(k, 0) if freq and hasattr(freq, 'get') else 0
        if min_freq is None or f < min_freq:
            min_freq = f

def popitem(self):
    """Remove and return the `(key, value)` pair least recently used."""
    # Try to use OrderedDict's popitem with last=False if available
    try:
        return super().popitem(last=False)
    except TypeError:
        # Fallback for plain dicts or older OrderedDict implementations
        if not self:
            raise KeyError('popitem(): dictionary is empty')
        # In a plain dict, the order is arbitrary; we choose the first key
        key = next(iter(self))
        value = self[key]
        del self[key]
        return key, value
    except AttributeError:
        # If the superclass doesn't provide popitem, fall back to manual removal
        if not self:
            raise KeyError('popitem(): dictionary is empty')
        key = next(iter(self))
        value = self[key]
        del self[key]
        return key, value

def popitem(self):
    """Remove and return the `(key, value)` pair most recently used."""
    if not self:
        raise KeyError('popitem(): dictionary is empty')
    return super().popitem()

