def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    if request is None:
        raise TypeError("request must not be None")
    try:
        # Check public message first
        pub = getattr(request, 'public_message', None)
        if pub is not None:
            if isinstance(pub, dict):
                if 'diaspora' in pub:
                    return True
            elif isinstance(pub, str):
                if 'diaspora' in pub.lower():
                    return True

        # Check private message
        priv = getattr(request, 'private_message', None)
        if priv is not None:
            if isinstance(priv, dict):
                if 'diaspora' in priv:
                    return True
            elif isinstance(priv, str):
                if 'diaspora' in priv.lower():
                    return True

        # Check legacy payload
        payload = getattr(request, 'payload', None)
        if payload is not None:
            if isinstance(payload, dict):
                if payload.get('legacy') is True:
                    return True
            elif isinstance(payload, str):
                if 'legacy' in payload.lower():
                    return True

        return False
    except Exception:
        # In case of any unexpected error, treat as not a Diaspora request
        return False

def identify_request(request: RequestType) -> bool:
    """Try to identify whether this is a Matrix request"""
    try:
        # If request is None or not the expected type, return False
        if request is None:
            return False

        # Check for a typical Matrix path prefix
        if hasattr(request, "path"):
            try:
                if request.path.startswith("/_matrix/"):
                    return True
            except Exception:
                pass

        # Check for JSON body via a .json attribute (common in frameworks)
        if hasattr(request, "json"):
            try:
                data = request.json
                if isinstance(data, dict):
                    # Common Matrix request keys
                    if any(k in data for k in ("action", "room_id", "type", "event_id", "user_id")):
                        return True
            except Exception:
                pass

        # Fallback: inspect headers and raw body
        if hasattr(request, "headers"):
            try:
                content_type = request.headers.get("Content-Type", "")
                if "application/json" in content_type:
                    body = getattr(request, "body", None)
                    if body:
                        try:
                            import json
                            data = json.loads(body)
                            if isinstance(data, dict):
                                if any(k in data for k in ("action", "room_id", "type", "event_id", "user_id")):
                                    return True
                        except Exception:
                            pass
            except Exception:
                pass

        return False
    except Exception:
        # Any unexpected error results in a conservative False
        return False

def format_dt(dt):
    """Format a datetime in the way that D* nodes expect."""
    import datetime
    if dt is None:
        raise ValueError("dt must not be None")
    if isinstance(dt, datetime.datetime):
        # Convert to UTC and format as ISO 8601 with trailing 'Z'
        if dt.tzinfo is None:
            dt_utc = dt
        else:
            dt_utc = dt.astimezone(datetime.timezone.utc)
        return dt_utc.strftime("%Y-%m-%dT%H:%M:%SZ")
    elif isinstance(dt, datetime.date):
        # Date only
        return dt.strftime("%Y-%m-%d")
    else:
        raise TypeError("dt must be a datetime.datetime or datetime.date instance")

def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    if not isinstance(text, str):
        raise TypeError("text must be a string")

    import re

    # Add attributes to existing <a> tags
    def _add_attrs(match):
        tag = match.group(0)
        # Skip if target already present
        if re.search(r'\btarget\s*=', tag, re.IGNORECASE):
            return tag
        # Insert target and rel before the closing '>'
        return re.sub(r'>', ' target="_blank" rel="noopener noreferrer">', tag, count=1)

    try:
        text = re.sub(r'<a\b[^>]*>', _add_attrs, text, flags=re.IGNORECASE)
    except re.error:
        # If regex fails, return original text
        pass

    # Linkify textual URLs
    url_pattern = re.compile(r'(?P<url>(?:https?://|www\.)[^\s<]+)', re.IGNORECASE)

    def _replace_url(match):
        url = match.group('url')
        href = url
        if url.lower().startswith('www.'):
            href = 'http://' + url
        return f'<a href="{href}" target="_blank" rel="noopener noreferrer">{url}</a>'

    try:
        text = url_pattern.sub(_replace_url, text)
    except re.error:
        # If regex fails, return original text
        pass

    return text

def fetch_content_type(url: str) -> Optional[str]:
    """Fetch the HEAD of the remote url to determine the content type."""
    try:
        import urllib.request, urllib.error
        req = urllib.request.Request(url, method='HEAD')
        with urllib.request.urlopen(req, timeout=10) as resp:
            return resp.headers.get('Content-Type')
    except Exception:
        return None

def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    import re

    if not isinstance(tag, str):
        raise TypeError("tag must be a string")

    # Empty string is not a valid tag
    if not tag:
        return False

    # A tag must start with a letter or underscore, and may contain
    # letters, digits, hyphens, underscores, and colons (for namespaces).
    pattern = re.compile(r'^[A-Za-z_][A-Za-z0-9_-:]*$')
    return bool(pattern.match(tag))

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    if node is None:
        return {}
    try:
        children = list(node)
    except Exception as e:
        raise TypeError("Provided node is not iterable or not an XML element") from e
    result = {}
    for child in children:
        try:
            tag = child.tag
        except AttributeError as e:
            raise AttributeError("Child node does not have a 'tag' attribute") from e
        if tag in result:
            existing = result[tag]
            if isinstance(existing, list):
                existing.append(child)
            else:
                result[tag] = [existing, child]
        else:
            result[tag] = child
    return result

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    import xml.etree.ElementTree as ET

    try:
        doc = document.strip()
        # Try JSON first
        if doc.startswith('{') or doc.startswith('['):
            return json.loads(doc)

        # Otherwise assume XRD (XML)
        root = ET.fromstring(doc)
        ns = {'xrd': 'http://docs.oasis-open.org/ns/xri/xrd-1.0'}

        result: Dict = {}

        subject = root.find('xrd:Subject', ns)
        if subject is not None and subject.text:
            result['subject'] = subject.text

        aliases = [a.text for a in root.findall('xrd:Alias', ns) if a.text]
        if aliases:
            result['aliases'] = aliases

        links = []
        for link in root.findall('xrd:Link', ns):
            link_dict: Dict = {}
            # Include all attributes of the <Link> element
            for attr_name, attr_value in link.attrib.items():
                link_dict[attr_name] = attr_value
            # Include any nested text (rare but possible)
            if link.text and link.text.strip():
                link_dict['text'] = link.text.strip()
            links.append(link_dict)

        if links:
            result['links'] = links

        return result

    except Exception:
        # In case of any parsing error, return an empty dict
        return {}

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """Try to retrieve an RFC7033 webfinger document. Does not raise if it fails."""
    try:
        if '@' not in handle:
            return None
        domain = handle.split('@', 1)[1]
        url = f"https://{domain}/.well-known/webfinger?resource=acct:{handle}"
        import requests
        resp = requests.get(url, timeout=5)
        if resp.status_code == 200:
            return resp.text
        return None
    except Exception:
        return None

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type
    """
    # Validate input types
    if not isinstance(settings_dirs, (list, tuple)):
        raise TypeError("settings_dirs must be a list or tuple of directory paths")
    if spec_option is not None and not isinstance(spec_option, str):
        raise TypeError("spec_option must be a string pattern or None")

    file_list = []
    for dir_path in settings_dirs:
        try:
            for entry in os.listdir(dir_path):
                full_path = os.path.join(dir_path, entry)
                if os.path.isfile(full_path):
                    if spec_option is None or fnmatch.fnmatch(entry, spec_option):
                        file_list.append(full_path)
        except OSError:
            # Skip directories that cannot be accessed
            continue

    return file_list

@classmethod
    def ansible_config_manager(cls):
        """Gets the ansible config manager. """
        # Use a class-level cache to avoid recreating the manager
        if not hasattr(cls, "_ansible_config_manager"):
            try:
                # Assume AnsibleConfigManager is defined elsewhere in the codebase
                cls._ansible_config_manager = AnsibleConfigManager()
            except Exception as exc:
                # Wrap any unexpected errors in a RuntimeError with context
                raise RuntimeError("Failed to instantiate AnsibleConfigManager") from exc
        return cls._ansible_config_manager

