@classmethod
    def validate_from_content(cls, spec_content=None):
        """validates that spec (YAML) content has all required fields

        :param spec_content: content of spec file
        :raise IRValidatorException: when mandatory data
        is missing in spec file
        :return: Dictionary with data loaded from a spec (YAML) file
        """
        if spec_content is None:
            raise IRValidatorException("No spec content provided")

        # Parse YAML if a string is given, otherwise use the dict directly
        if isinstance(spec_content, str):
            try:
                import yaml
                spec_dict = yaml.safe_load(spec_content)
            except Exception as exc:
                raise IRValidatorException(f"Failed to parse YAML: {exc}")
        elif isinstance(spec_content, dict):
            spec_dict = spec_content
        else:
            raise IRValidatorException(
                f"Unsupported spec_content type: {type(spec_content).__name__}"
            )

        if not isinstance(spec_dict, dict):
            raise IRValidatorException(
                f"Spec content did not resolve to a dictionary, got {type(spec_dict).__name__}"
            )

        # Validate required fields
        required_fields = getattr(cls, "REQUIRED_FIELDS", [])
        missing = [field for field in required_fields if field not in spec_dict]
        if missing:
            raise IRValidatorException(
                f"Missing required fields in spec: {', '.join(missing)}"
            )

        return spec_dict

def validate_from_file(cls, yaml_file=None):
        """Loads & validates that a YAML file has all required fields

        :param yaml_file: Path to YAML file
        :raise IRValidatorException: when mandatory data is missing in file
        :return: Dictionary with data loaded from a YAML file
        """
        if yaml_file is None:
            raise IRValidatorException("No YAML file specified")

        try:
            with open(yaml_file, 'r', encoding='utf-8') as f:
                data = yaml.safe_load(f)
        except FileNotFoundError as e:
            raise IRValidatorException(f"YAML file not found: {yaml_file}") from e
        except yaml.YAMLError as e:
            raise IRValidatorException(f"Error parsing YAML file: {yaml_file}") from e

        if not isinstance(data, dict):
            raise IRValidatorException("YAML file does not contain a mapping at the top level")

        required = getattr(cls, 'REQUIRED_FIELDS', [])
        missing = [field for field in required if field not in data]
        if missing:
            raise IRValidatorException(f"Missing required fields in YAML file: {', '.join(missing)}")

        return data

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    def _resolve(group, visited):
        if group not in parser_dict:
            raise ValueError(f"Group '{group}' not found in parser_dict.")
        if group in visited:
            raise ValueError(f"Circular include detected for group '{group}'.")
        visited.add(group)

        group_dict = parser_dict[group]
        includes = group_dict.get('include')
        if includes:
            # Normalise to a list
            if isinstance(includes, str):
                includes = [includes]
            elif not isinstance(includes, (list, tuple)):
                raise TypeError(f"Include value for group '{group}' must be a string or list/tuple of strings.")

            for inc in includes:
                _resolve(inc, visited)
                inc_dict = parser_dict[inc]
                # Merge inc_dict into group_dict, skipping the 'include' key itself
                for k, v in inc_dict.items():
                    if k == 'include':
                        continue
                    group_dict[k] = v

            # Remove the include key after processing
            group_dict.pop('include', None)

        visited.remove(group)

    # Resolve all groups in the dictionary
    for grp in list(parser_dict.keys()):
        _resolve(grp, set())

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    # Validate that the object has a spec attribute and it is a dictionary
    if not hasattr(self, 'spec'):
        raise AttributeError("Missing required 'spec' attribute")
    if not isinstance(self.spec, dict):
        raise TypeError("'spec' must be a dictionary")

    resolved = {}
    for key, value in self.spec.items():
        # Use the value from spec if it is not None
        if value is not None:
            resolved[key] = value
            continue

        # Try to obtain a default from a 'defaults' attribute if present
        try:
            defaults_attr = getattr(self, 'defaults', None)
            if isinstance(defaults_attr, dict) and key in defaults_attr:
                resolved[key] = defaults_attr[key]
                continue
        except Exception:
            # Ignore any errors while accessing defaults
            pass

        # Try to obtain a default from a 'config' attribute if present
        try:
            config_attr = getattr(self, 'config', None)
            if isinstance(config_attr, dict) and key in config_attr:
                resolved[key] = config_attr[key]
                continue
        except Exception:
            # Ignore any errors while accessing config
            pass

        # If no source provided a value, default to None
        resolved[key] = None

    return resolved

def get_deprecated_args(self):
    """Returning dict with options which deprecate others."""
    return {}

def validate_arg_deprecation(self, cli_args, answer_file_args):
    """Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """
    # The class may define a set of deprecated argument names in an attribute
    # called ``deprecated_args``.  If it is present, we check both the CLI
    # arguments and the answer‑file arguments for any of those names and
    # emit a warning.  The deprecated arguments are removed from the
    # dictionaries so that downstream code does not see them.
    try:
        deprecated = getattr(self, "deprecated_args", None)
        if not deprecated:
            return

        for source_name, args in (("CLI", cli_args), ("answer file", answer_file_args)):
            if not isinstance(args, dict):
                continue
            # Collect keys to avoid modifying the dict while iterating
            for key in list(args.keys()):
                if key in deprecated:
                    print(f"Warning: Argument '{key}' from {source_name} is deprecated and will be ignored.")
                    args.pop(key)
    except Exception as exc:
        # If something unexpected happens we raise a RuntimeError with a
        # clear message so that callers can handle it appropriately.
        raise RuntimeError(f"Error while validating deprecated arguments: {exc}") from exc

def get_parser_option_specs(self, command_name):
    """Gets all the options for the specified command

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    # Normalise the command name
    if command_name is None:
        command_name = "main"
    if not isinstance(command_name, str):
        raise TypeError("command_name must be a string")

    # Retrieve the dictionary that holds the option specs
    options_dict = getattr(self, "parser_options", None)
    if options_dict is None:
        options_dict = getattr(self, "_parser_options", None)
    if options_dict is None:
        raise AttributeError("No parser options defined on this object")

    # Ensure the command exists
    if command_name not in options_dict:
        raise ValueError(f"Unknown command name: {command_name!r}")

    # Return a copy to avoid accidental mutation
    return list(options_dict[command_name])

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name. """
    # Validate input types
    if not isinstance(command_name, str):
        raise TypeError("command_name must be a string")
    if not isinstance(argument_name, str):
        raise TypeError("argument_name must be a string")

    # Retrieve the command object
    try:
        command = self.commands[command_name]
    except Exception as exc:
        raise KeyError(f"Command '{command_name}' not found") from exc

    # Retrieve the option specification from the command
    try:
        # Prefer a dedicated 'options' attribute, fall back to 'arguments'
        options = getattr(command, "options", getattr(command, "arguments", {}))
        spec = options[argument_name]
    except Exception as exc:
        raise KeyError(
            f"Option '{argument_name}' not found in command '{command_name}'"
        ) from exc

    return spec

def get_silent_args(self, args):
    """list of silenced argument

    :param args: The received arguments.
    :return: list, slienced argument names
    """
    silent = []
    if args is None:
        return silent

    # Handle dictionary of arguments
    if isinstance(args, dict):
        for key, value in args.items():
            if value is None or value == '':
                silent.append(key)

    # Handle list/tuple of (name, value) pairs
    elif isinstance(args, (list, tuple)):
        for item in args:
            if isinstance(item, (list, tuple)) and len(item) == 2:
                key, value = item
                if value is None or value == '':
                    silent.append(key)

    # Fallback: try to iterate over args as key/value pairs
    else:
        try:
            for key, value in args:
                if value is None or value == '':
                    silent.append(key)
        except Exception:
            # If args is not iterable or not in expected format, ignore
            pass

    return silent

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided. """
    if args is None:
        raise ValueError("No arguments provided")
    # Ensure args is a mapping; try to convert if possible
    if not isinstance(args, dict):
        try:
            args = dict(args)
        except Exception as exc:
            raise TypeError("args must be a mapping or convertible to dict") from exc
    required = getattr(self, 'REQUIRED_ARGS', [])
    for name in required:
        if name not in args or args[name] is None:
            raise ValueError(f"Missing required argument: {name}")
    return True

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    required = []
    for opt in options_spec:
        # allow dict or object with attributes
        try:
            name = opt.get('name') if isinstance(opt, dict) else getattr(opt, 'name', None)
            cond = opt.get('required_when') if isinstance(opt, dict) else getattr(opt, 'required_when', None)
        except Exception:
            continue

        if not name or not cond:
            continue

        try:
            # If condition is callable, call it with args
            if callable(cond):
                match = cond(args)
            else:
                # Assume string expression; evaluate safely
                # Provide args in local namespace
                match = eval(cond, {}, {'args': args})
        except Exception:
            # If evaluation fails, treat as not matched
            match = False

        if match:
            required.append(name)
    return required

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    # If no arguments provided, nothing to validate
    if args is None:
        return True

    # Helper to validate a single argument
    def _check(name, value, max_len):
        if value is None:
            return
        try:
            length = len(value)
        except Exception:
            # Value has no length; skip validation
            return
        if max_len is not None and length > max_len:
            raise ValueError(
                f"Argument '{name}' length {length} exceeds maximum allowed {max_len}"
            )

    # Case 1: args is a mapping of name -> value
    if isinstance(args, dict):
        # Attempt to get a mapping of name -> max length from the instance
        max_lengths = getattr(self, "arg_lengths", {})
        for name, value in args.items():
            max_len = max_lengths.get(name)
            _check(name, value, max_len)
        return True

    # Case 2: args is an iterable of tuples (name, value, max_len)
    if isinstance(args, (list, tuple)):
        for item in args:
            if not isinstance(item, (list, tuple)) or len(item) != 3:
                raise TypeError(
                    "When args is a list/tuple, each element must be a tuple of (name, value, max_len)"
                )
            name, value, max_len = item
            _check(name, value, max_len)
        return True

    # Unsupported type
    raise TypeError("args must be a dict or a list/tuple of (name, value, max_len) tuples")

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    if args is None:
        return
    if not isinstance(args, dict):
        raise TypeError("args must be a dictionary of argument names to values")
    # Retrieve the mapping of allowed choices; default to empty dict if not present
    allowed_choices = getattr(self, "choices", {})
    for key, value in args.items():
        if key in allowed_choices:
            allowed = allowed_choices[key]
            if value not in allowed:
                raise ValueError(
                    f"Invalid value for argument '{key}': {value}. "
                    f"Allowed values: {allowed}"
                )
    # If no issues, simply return (or could return True)"""

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    # Determine the number of arguments supplied
    if args is None:
        count = 0
    else:
        try:
            count = len(args)
        except Exception:
            # If args is not a sequence, treat it as a single argument
            count = 1

    # Retrieve optional minimum and maximum limits from the instance
    min_args = getattr(self, "MIN_ARGS", None)
    max_args = getattr(self, "MAX_ARGS", None)

    # Validate against the minimum limit
    if min_args is not None and count < min_args:
        raise ValueError(
            f"Too few arguments: expected at least {min_args}, got {count}."
        )

    # Validate against the maximum limit
    if max_args is not None and count > max_args:
        raise ValueError(
            f"Too many arguments: expected at most {max_args}, got {count}."
        )

    return True

def create_complex_argumet_type(self, subcommand, type_name, option_name,
                                    spec_option):
        """Build the complex argument type

        :param subcommand: the command name
        :param type_name: the complex type name
        :param option_name: the option name
        :param spec_option: option's specifications
        :return: the complex type instance
        """
        # Basic validation of inputs
        if not isinstance(subcommand, str):
            raise TypeError("subcommand must be a string")
        if not isinstance(type_name, str):
            raise TypeError("type_name must be a string")
        if not isinstance(option_name, str):
            raise TypeError("option_name must be a string")
        if not isinstance(spec_option, dict):
            raise TypeError("spec_option must be a dict")

        class ComplexArgumentType:
            def __init__(self, subcommand, type_name, option_name, spec_option):
                self.subcommand = subcommand
                self.type_name = type_name
                self.option_name = option_name
                self.spec_option = spec_option

            def __call__(self, value):
                # Apply type conversion if specified
                try:
                    if 'type' in self.spec_option:
                        value = self.spec_option['type'](value)
                except Exception as e:
                    raise ValueError(f"Failed to convert value for {self.option_name}: {e}") from e

                # Check allowed choices
                if 'choices' in self.spec_option:
                    if value not in self.spec_option['choices']:
                        raise ValueError(
                            f"Invalid value for {self.option_name}: {value}. "
                            f"Expected one of {self.spec_option['choices']}"
                        )

                # Custom validator
                if 'validator' in self.spec_option:
                    validator = self.spec_option['validator']
                    if callable(validator):
                        try:
                            if not validator(value):
                                raise ValueError(
                                    f"Validator rejected value for {self.option_name}: {value}"
                                )
                        except Exception as e:
                            raise ValueError(
                                f"Validator error for {self.option_name}: {e}"
                            ) from e
                    else:
                        raise TypeError("validator must be callable")

                return value

            def __repr__(self):
                return f"<ComplexArgumentType {self.type_name} for {self.option_name}>"

        return ComplexArgumentType(subcommand, type_name, option_name, spec_option)

def get_nested_custom_and_control_args(self, args):
        """Split input arguments to control nested and custom.

        Controls arguments: control the IR behavior. These arguments
            will not be put into the spec yml file
        Nested arguments: are used by the Ansible playbooks and will be put
            into the spec yml file.
        Custom arguments: Custom ansible variables to be used instead of the
            normal nested usage.

        :param args: the collected list of args.
        :return: (dict, dict): flat dicts (control_args, nested_args)
        """
        # Prepare result dictionaries
        control_args = {}
        nested_args = {}

        # If no arguments provided, return empty dicts
        if not args:
            return control_args, nested_args

        # Normalize input to iterable of key/value pairs
        if isinstance(args, dict):
            items = args.items()
        elif isinstance(args, (list, tuple)):
            # Expect list of tuples or dicts
            items = []
            for item in args:
                if isinstance(item, dict):
                    items.extend(item.items())
                elif isinstance(item, (list, tuple)) and len(item) == 2:
                    items.append((item[0], item[1]))
                else:
                    raise ValueError(f"Unsupported argument format: {item!r}")
        else:
            raise TypeError(f"args must be a dict or list/tuple of key/value pairs, got {type(args).__name__}")

        # Split into control and nested arguments
        for key, value in items:
            if not isinstance(key, str):
                raise TypeError(f"Argument key must be a string, got {type(key).__name__}")
            # Define control keys: start with '_' or 'control_'
            if key.startswith('_') or key.lower().startswith('control_'):
                control_args[key] = value
            else:
                nested_args[key] = value

        return control_args, nested_args

@staticmethod
    def merge_extra_vars(vars_dict, extra_vars=None):
        """Extend ``vars_dict`` with ``extra-vars``

        :param vars_dict: Dictionary to merge extra-vars into
        :param extra_vars: List of extra-vars
        """
        # Validate input dictionary
        if not isinstance(vars_dict, dict):
            raise TypeError(f"vars_dict must be a dict, got {type(vars_dict).__name__}")

        # Nothing to merge
        if extra_vars is None:
            return vars_dict

        # Helper to update dictionary from a mapping
        def _update_from_mapping(mapping):
            if not isinstance(mapping, dict):
                raise TypeError(f"Expected dict for mapping, got {type(mapping).__name__}")
            vars_dict.update(mapping)

        # If extra_vars is a dict, merge directly
        if isinstance(extra_vars, dict):
            _update_from_mapping(extra_vars)
            return vars_dict

        # If it's a string, try to parse key=value pairs separated by commas
        if isinstance(extra_vars, str):
            # Split on commas, but ignore empty parts
            parts = [p.strip() for p in extra_vars.split(',') if p.strip()]
            for part in parts:
                if '=' not in part:
                    raise ValueError(f"Invalid extra_vars string format: '{part}'. Expected 'key=value'.")
                key, value = part.split('=', 1)
                vars_dict[key.strip()] = value.strip()
            return vars_dict

        # If it's an iterable (list/tuple) of items
        if isinstance(extra_vars, (list, tuple)):
            for item in extra_vars:
                # Mapping
                if isinstance(item, dict):
                    _update_from_mapping(item)
                # Tuple/list of length 2
                elif isinstance(item, (list, tuple)) and len(item) == 2:
                    key, value = item
                    if key is None:
                        raise ValueError("Key in extra_vars tuple cannot be None")
                    vars_dict[key] = value
                # String key=value
                elif isinstance(item, str):
                    if '=' not in item:
                        raise ValueError(f"Invalid extra_vars string format: '{item}'. Expected 'key=value'.")
                    key, value = item.split('=', 1)
                    vars_dict[key.strip()] = value.strip()
                else:
                    raise TypeError(f"Unsupported item type in extra_vars: {type(item).__name__}")
            return vars_dict

        # Unsupported type
        raise TypeError(f"Unsupported type for extra_vars: {type(extra_vars).__name__}")

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json
    import yaml
    from pathlib import Path

    def _flatten(d, parent_key='', sep='.'):
        items = {}
        if isinstance(d, dict):
            for k, v in d.items():
                new_key = f"{parent_key}{sep}{k}" if parent_key else k
                items.update(_flatten(v, new_key, sep=sep))
        elif isinstance(d, list):
            for idx, v in enumerate(d):
                new_key = f"{parent_key}{sep}{idx}" if parent_key else str(idx)
                items.update(_flatten(v, new_key, sep=sep))
        else:
            items[parent_key] = d
        return items

    plugin_path = Path(plugin_dir)
    if not plugin_path.is_dir():
        raise FileNotFoundError(f"Plugin directory '{plugin_dir}' does not exist or is not a directory.")

    # Look for common spec file names
    spec_file = None
    for name in ('plugin.json', 'plugin.yaml', 'plugin.yml'):
        candidate = plugin_path / name
        if candidate.is_file():
            spec_file = candidate
            break

    if spec_file is None:
        raise FileNotFoundError(f"No plugin spec file found in '{plugin_dir}'. Expected one of: plugin.json, plugin.yaml, plugin.yml")

    try:
        with spec_file.open('r', encoding='utf-8') as f:
            if spec_file.suffix in {'.json'}:
                data = json.load(f)
            else:
                data = yaml.safe_load(f)
    except Exception as e:
        raise ValueError(f"Failed to load plugin spec from '{spec_file}': {e}")

    if not isinstance(data, dict):
        raise ValueError(f"Plugin spec in '{spec_file}' must be a mapping (dict), got {type(data).__name__}")

    return _flatten(data)

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    import os
    env_var = 'CONFIG_PATH'
    if not os.getenv(env_var):
        try:
            default_path = os.path.join(os.getcwd(), 'config.yaml')
            os.environ[env_var] = default_path
        except Exception:
            # Silently ignore any errors setting the environment variable
            pass
